106	/// Class that wraps the __tgt_async_info to simply its usage. In case the
107	/// object is constructed without a valid __tgt_async_info, the object will use
108	/// an internal one and will synchronize the current thread with the pending
109	/// operations when calling AsyncInfoWrapperTy::finalize(). This latter function
110	/// must be called before destroying the wrapper object.
111	struct AsyncInfoWrapperTy {
112	  AsyncInfoWrapperTy(GenericDeviceTy &Device, __tgt_async_info *AsyncInfoPtr);
113	
114	  ~AsyncInfoWrapperTy() {
115	    assert(!AsyncInfoPtr && "AsyncInfoWrapperTy not finalized");
116	  }
117	
118	  /// Get the raw __tgt_async_info pointer.
119	  operator __tgt_async_info *() const { return AsyncInfoPtr; }
120	
121	  /// Indicate whether there is queue.
122	  bool hasQueue() const { return (AsyncInfoPtr->Queue != nullptr); }
123	
124	  /// Get the queue.
125	  template <typename Ty> Ty getQueueAs() {
126	    static_assert(sizeof(Ty) == sizeof(AsyncInfoPtr->Queue),
127	                  "Queue is not of the same size as target type");
128	    return static_cast<Ty>(AsyncInfoPtr->Queue);
129	  }
130	
131	  /// Set the queue.
132	  template <typename Ty> void setQueueAs(Ty Queue) {
133	    static_assert(sizeof(Ty) == sizeof(AsyncInfoPtr->Queue),
134	                  "Queue is not of the same size as target type");
135	    assert(!AsyncInfoPtr->Queue && "Overwriting queue");
136	    AsyncInfoPtr->Queue = Queue;
137	  }
138	
139	  /// Get the queue, using the provided resource manager to initialise it if it
140	  /// doesn't exist.
141	  template <typename Ty, typename RMTy>
142	  Expected<Ty>
143	  getOrInitQueue(GenericDeviceResourceManagerTy<RMTy> &ResourceManager) {
144	    std::lock_guard<std::mutex> Lock(AsyncInfoPtr->Mutex);
145	    if (!AsyncInfoPtr->Queue) {
146	      if (auto Err = ResourceManager.getResource(
147	              *reinterpret_cast<Ty *>(&AsyncInfoPtr->Queue)))
148	        return Err;
149	    }
150	    return getQueueAs<Ty>();
151	  }
152	
153	  /// Explicitly synchronize with the __tgt_async_info's pending operations
154	  /// regardless of which async info this object wraps. The associated
155	  /// underlying queue (if any) will not be released. Calling this function does
156	  /// not obviate the need to call the finalize function later. This function is
157	  /// intended for specific use cases where a synchronous operation needs to
158	  /// explicitly wait for the operations already on the queue.
159	  Error synchronize();
160	
161	  /// Synchronize with the __tgt_async_info's pending operations if it's the
162	  /// internal async info. The error associated to the asynchronous operations
163	  /// issued in this queue must be provided in \p Err. This function will update
164	  /// the error parameter with the result of the synchronization if it was
165	  /// actually executed. This function must be called before destroying the
166	  /// object and only once.
167	  void finalize(Error &Err);
168	
169	  /// Register \p Ptr as an associated allocation that is freed after
170	  /// finalization.
171	  void freeAllocationAfterSynchronization(void *Ptr) {
172	    std::lock_guard<std::mutex> AllocationGuard(AsyncInfoPtr->Mutex);
173	    AsyncInfoPtr->AssociatedAllocations.push_back(Ptr);
174	  }
175	
176	private:
177	  GenericDeviceTy &Device;
178	  __tgt_async_info LocalAsyncInfo;
179	  __tgt_async_info *AsyncInfoPtr;
180	};
