188	/// Tree node for device information
189	///
190	/// This information is either printed or used by liboffload to extract certain
191	/// device queries. Each property has an optional key, an optional value
192	/// and optional children. The children can be used to store additional
193	/// information (such as x, y and z components of ranges).
194	struct InfoTreeNode {
195	  static constexpr uint64_t IndentSize = 4;
196	
197	  std::string Key;
198	  using VariantType = std::variant<uint64_t, std::string, bool, std::monostate>;
199	  VariantType Value;
200	  std::string Units;
201	  // Need to specify a default value number of elements here as `InfoTreeNode`'s
202	  // size is unknown. This is a vector (rather than a Key->Value map) since:
203	  // * The keys need to be owned and thus `std::string`s
204	  // * The order of keys is important
205	  // * The same key can appear multiple times
206	  std::unique_ptr<llvm::SmallVector<InfoTreeNode, 8>> Children;
207	
208	  llvm::DenseMap<DeviceInfo, size_t> DeviceInfoMap;
209	
210	  InfoTreeNode() : InfoTreeNode("", std::monostate{}, "") {}
211	  InfoTreeNode(std::string Key, VariantType Value, std::string Units)
212	      : Key(std::move(Key)), Value(Value), Units(std::move(Units)) {}
213	
214	  /// Add a new info entry as a child of this node. The entry requires at least
215	  /// a key string in \p Key. The value in \p Value is optional and can be any
216	  /// type that is representable as a string. The units in \p Units is optional
217	  /// and must be a string. Providing a device info key allows liboffload to
218	  /// use that value for an appropriate olGetDeviceInfo query
219	  template <typename T = std::monostate>
220	  InfoTreeNode *add(std::string Key, T Value = T(),
221	                    std::string Units = std::string(),
222	                    std::optional<DeviceInfo> DeviceInfoKey = std::nullopt) {
223	    assert(!Key.empty() && "Invalid info key");
224	
225	    if (!Children)
226	      Children = std::make_unique<llvm::SmallVector<InfoTreeNode, 8>>();
227	
228	    VariantType ValueVariant;
229	    if constexpr (std::is_same_v<T, bool> || std::is_same_v<T, std::monostate>)
230	      ValueVariant = Value;
231	    else if constexpr (std::is_arithmetic_v<T>)
232	      ValueVariant = static_cast<uint64_t>(Value);
233	    else
234	      ValueVariant = std::string{Value};
235	
236	    auto Ptr =
237	        &Children->emplace_back(std::move(Key), ValueVariant, std::move(Units));
238	
239	    if (DeviceInfoKey)
240	      DeviceInfoMap[*DeviceInfoKey] = Children->size() - 1;
241	
242	    return Ptr;
243	  }
244	
245	  std::optional<InfoTreeNode *> get(StringRef Key) {
246	    if (!Children)
247	      return std::nullopt;
248	
249	    auto It = std::find_if(Children->begin(), Children->end(),
250	                           [&](auto &V) { return V.Key == Key; });
251	    if (It == Children->end())
252	      return std::nullopt;
253	    return It;
254	  }
255	
256	  std::optional<InfoTreeNode *> get(DeviceInfo Info) {
257	    auto Result = DeviceInfoMap.find(Info);
258	    if (Result != DeviceInfoMap.end())
259	      return &(*Children)[Result->second];
260	    return std::nullopt;
261	  }
262	
263	  /// Print all info entries in the tree
264	  void print() const {
265	    // Fake an additional indent so that values are offset from the keys
266	    doPrint(0, maxKeySize(1));
267	  }
268	
269	private:
270	  void doPrint(int Level, uint64_t MaxKeySize) const {
271	    if (Key.size()) {
272	      // Compute the indentations for the current entry.
273	      uint64_t KeyIndentSize = Level * IndentSize;
274	      uint64_t ValIndentSize =
275	          MaxKeySize - (Key.size() + KeyIndentSize) + IndentSize;
276	
277	      llvm::outs() << std::string(KeyIndentSize, ' ') << Key
278	                   << std::string(ValIndentSize, ' ');
279	      std::visit(
280	          [](auto &&V) {
281	            using T = std::decay_t<decltype(V)>;
282	            if constexpr (std::is_same_v<T, std::string>)
283	              llvm::outs() << V;
284	            else if constexpr (std::is_same_v<T, bool>)
285	              llvm::outs() << (V ? "Yes" : "No");
286	            else if constexpr (std::is_same_v<T, uint64_t>)
287	              llvm::outs() << V;
288	            else if constexpr (std::is_same_v<T, std::monostate>) {
289	              // Do nothing
290	            } else
291	              static_assert(false, "doPrint visit not exhaustive");
292	          },
293	          Value);
294	      llvm::outs() << (Units.empty() ? "" : " ") << Units << "\n";
295	    }
296	
297	    // Print children
298	    if (Children)
299	      for (const auto &Entry : *Children)
300	        Entry.doPrint(Level + 1, MaxKeySize);
301	  }
302	
303	  // Recursively calculates the maximum width of each key, including indentation
304	  uint64_t maxKeySize(int Level) const {
305	    uint64_t MaxKeySize = 0;
306	
307	    if (Children)
308	      for (const auto &Entry : *Children) {
309	        uint64_t KeySize = Entry.Key.size() + Level * IndentSize;
310	        MaxKeySize = std::max(MaxKeySize, KeySize);
311	        MaxKeySize = std::max(MaxKeySize, Entry.maxKeySize(Level + 1));
312	      }
313	
314	    return MaxKeySize;
315	  }
316	};
